#!/usr/bin/env python3
"""Generate B7/JHS1 assessment questions for Flawlex Mastery.
27 topics x 20 questions = 540 questions total.
Each topic: 6 easy/recall, 8 core/application, 6 bece_level/analysis
16 MCQ + 4 fill-in-blank per topic
"""
import os
import uuid
import json

def esc(text):
    return text.replace("'", "''")

def make_uuid(topic_code, idx):
    return str(uuid.uuid5(uuid.NAMESPACE_DNS, f'q-{topic_code}-{idx}'))

def q(stem, opts, ans, exp, hints, diff, bloom, qtype='mcq'):
    return {'stem': stem, 'opts': opts, 'ans': ans, 'exp': exp, 'hints': hints, 'diff': diff, 'bloom': bloom, 'type': qtype}

